'use client';
import Link from'next/link';import{useEffect,useState}from'react';import{request,Vendor}from'../../lib/api';
export default function Settings(){const[t,setT]=useState('');const[v,setV]=useState<Vendor>();const[msg,setMsg]=useState('');useEffect(()=>{const x=localStorage.getItem('foodcart.vendor')||'';setT(x);if(x)request<Vendor>('/api/vendor/me',{},x).then(setV).catch(e=>setMsg(e.message))},[]);async function save(){try{const x=await request<Vendor>('/api/vendor/me/profile',{method:'PUT',body:JSON.stringify(v)},t);setV(x);setMsg('Saved. Your ordering page updates immediately.')}catch(e:any){setMsg(e.message)}}if(!v)return <main className="shell p-8">{msg||'Loading…'}</main>;return <main className="shell min-h-screen"><header className="px-5 py-6 text-white" style={{background:v.themeColor||'#102820'}}><div className="mx-auto flex max-w-4xl justify-between"><h1 className="text-3xl">Your storefront</h1><Link href="/vendor" className="text-xs font-bold">← DASHBOARD</Link></div></header><div className="mx-auto max-w-2xl p-5"><p className="text-xs font-bold tracking-widest text-clay">CUSTOMISE YOUR PUBLIC PAGE</p><div className="card mt-4 p-5"><label className="block text-xs font-bold">BUSINESS NAME<input className="mt-2 w-full rounded-xl border p-3" value={v.name||''} onChange={e=>setV({...v,name:e.target.value})}/></label><label className="mt-4 block text-xs font-bold">ADDRESS<input className="mt-2 w-full rounded-xl border p-3" value={v.address||''} onChange={e=>setV({...v,address:e.target.value})}/></label><label className="mt-4 block text-xs font-bold">DESCRIPTION<textarea className="mt-2 w-full rounded-xl border p-3" rows={3} value={v.description||''} onChange={e=>setV({...v,description:e.target.value})}/></label><label className="mt-5 block text-xs font-bold">BRAND COLOUR<input type="color" className="mt-2 block h-14 w-full rounded-xl border p-1" value={v.themeColor||'#102820'} onChange={e=>setV({...v,themeColor:e.target.value})}/></label><div className="mt-4 rounded-2xl p-5 text-white" style={{background:v.themeColor||'#102820'}}><p className="text-xs font-bold tracking-widest">LIVE PREVIEW</p><b className="mt-2 block text-2xl">{v.name}</b><p className="mt-1 text-sm opacity-80">{v.description}</p></div><button onClick={save} className="tap mt-5 w-full bg-lime">SAVE STOREFRONT</button>{msg&&<p className="mt-3 text-sm text-emerald-700">{msg}</p>}</div></div></main>}
